            id = "g_kids_1_3_1",
            lessonId = "lesson_kids_1_3",
            title = "Asking How Someone Is",
            titleVi = "Hỏi thăm sức khỏe và nói lời cảm ơn",
            explanation = "Use 'How are you?' to ask and 'I am fine, thank you!' to reply politely.",
            explanationVi = "1. HỎI THĂM SỨC KHỎE:\n- How are you? (Bạn khỏe không? / Bạn cảm thấy thế nào?)\n- How are you today? (Hôm nay bạn thế nào?)\n\n2. CÁC CÁCH TRẢ LỜI LỊCH SỰ:\n- I am fine, thank you. (Mình khỏe, cảm ơn bạn.)\n- I am good, thank you. (Mình rất tốt, cảm ơn bạn.)\n- I am great! (Mình cảm thấy tuyệt vời!)\n\n3. HỎI LẠI BẠN:\n- And you? (Còn bạn thì sao?)\n\n4. LỜI NÓI PHÉP THUẬT:\n- Luôn nói 'Thank you' khi nhận được sự quan tâm hay giúp đỡ từ người khác nhé!",
