            explanation = "Ask 'How many...?' and add 's' for more than one item.",
            explanationVi = "1. HỎI SỐ LƯỢNG:\n- How many + [Danh từ số nhiều thêm 's']?\n- Ví dụ: How many stars? (Có bao nhiêu ngôi sao?)\n\n2. TRẢ LỜI SỐ LƯỢNG:\n- Khi có 1 đồ vật (số ít): One star (Một ngôi sao - không thêm s).\n- Khi có từ 2 trở lên (số nhiều): Thêm 's' vào sau từ:\n  + Two stars (Hai ngôi sao)\n  + Three cats (Ba chú mèo)\n  + Four apples (Bốn quả táo)\n  + Five fingers (Năm ngón tay)",
            examples = listOf("How many cats? - Three cats.", "One apple, two apples.", "I have five fingers."),
            examplesVi = listOf("Có bao nhiêu chú mèo? - Ba chú mèo.", "Một quả táo, hai quả táo.", "Mình có năm ngón tay."),
            order = 1
        ),
        Grammar(
            id = "g_kids_3_2_1",
            lessonId = "lesson_kids_3_2",
            title = "Asking and Telling Age",
            titleVi = "Hỏi và trả lời về số tuổi",
            explanation = "Use 'How old are you?' to ask, and 'I am [number] years old' to reply.",
