            title = "Talking About Favorite Colors",
            titleVi = "Nói về màu sắc yêu thích nhất",
            explanation = "Use 'My favorite color is...' or 'I like...' to share preferences.",
            explanationVi = "1. NÓI VỀ MÀU YÊU THÍCH:\n- My favorite color is + [Tên màu].\n  + Ví dụ: My favorite color is pink. (Màu yêu thích của mình là màu hồng.)\n  + My favorite color is purple. (Màu yêu thích của mình là màu tím.)\n\n2. CÁCH NÓI ĐƠN GIẢN KHÁC:\n- I like + [Tên màu].\n  + Ví dụ: I like orange. (Mình thích màu cam.)\n  + I like white and blue. (Mình thích màu trắng và màu xanh.)\n\n3. LƯU Ý:\n- Từ 'Orange' vừa là quả cam (danh từ), vừa là màu cam (tính từ) đó bé!",
