            explanationVi = "1. GIỚI THIỆU THÀNH VIÊN GIA ĐÌNH:\n- This is my + [Thành viên gia đình].\n  + This is my dad. (Đây là bố của mình.)\n  + This is my mom. (Đây là mẹ của mình.)\n  + This is my baby sister. (Đây là em gái nhỏ của mình.)\n\n2. CÂU BÀY TỎ TÌNH YÊU THƯƠNG:\n- I love my family! (Con yêu gia đình của con!)\n- I love my mom! (Con yêu mẹ nhiều lắm!)",
            examples = listOf("This is my dad. He is strong.", "This is my mom. She is beautiful.", "I love my family very much."),
            examplesVi = listOf("Đây là bố của mình. Bố rất khỏe mạnh.", "Đây là mẹ của mình. Mẹ rất xinh đẹp.", "Con yêu gia đình của mình rất nhiều."),
            order = 1
        ),
        Grammar(
            id = "g_kids_5_2_1",
            lessonId = "lesson_kids_5_2",
            title = "Pronouns: He and She",
            titleVi = "Đại từ nhân xưng: He (Anh ấy, Cậu ấy) và She (Cô ấy, Bạn ấy)",
            explanation = "Use 'He' for boys and men, and 'She' for girls and women.",
            explanationVi = "1. DÙNG 'HE' (CẬU ẤY, ANH ẤY, BỐ, ÔNG):\n- He is my brother. (Cậu ấy là anh trai mình.)\n- He is tall. (Cậu ấy rất cao.)\n\n2. DÙNG 'SHE' (CÔ ẤY, BẠN ẤY, MẸ, BÀ):\n- She is my sister. (Bạn ấy là chị gái mình.)\n- She is kind and pretty. (Chị ấy rất tốt bụng và xinh xắn.)\n\n3. LƯU Ý DỄ NHỚ:\n- He đi với nam giới (bố, anh, em trai).\n- She đi với nữ giới (mẹ, chị, em gái).",
            examples = listOf("This is my brother. He is smart.", "This is my sister. She is cute.", "We play together happily."),
            examplesVi = listOf("Đây là anh trai mình. Anh ấy rất thông minh.", "Đây là em gái mình. Bé rất đáng yêu.", "Chúng mình chơi đùa cùng nhau thật hạnh phúc."),
            order = 1
        ),
        Grammar(
            id = "g_kids_5_3_1",
            lessonId = "lesson_kids_5_3",
            title = "Asking 'Who is this?'",
            titleVi = "Hỏi 'Đây là ai?' với 'Who is this?'",
            explanation = "Use 'Who is this?' to ask about someone, and answer 'This is my...'.",
            explanationVi = "1. HỎI ĐÂY LÀ AI:\n- Who is this? (Đây là ai thế?)\n- Who is that? (Kia là ai thế?)\n\n2. CÂU TRẢ LỜI:\n- This is my grandpa. (Đây là ông của mình.)\n- This is my grandma. (Đây là bà của mình.)\n- That is my puppy. (Kia là chú cún con của mình.)\n\n3. LƯU Ý TỪ VỰNG THÂN MẬT:\n- Grandpa = Grandfather (Ông)\n- Grandma = Grandmother (Bà)",
            examples = listOf("Who is this? - This is my grandpa.", "Who is that? - That is my grandma.", "I love my puppy and kitten."),
            examplesVi = listOf("Đây là ai? - Đây là ông của mình.", "Kia là ai? - Kia là bà của mình.", "Mình rất yêu chú cún con và mèo con của mình."),
            order = 1
        )
    )

